def summarize_occupancy(payload):
    if not isinstance(payload, dict):
        return "INVALID"

    tray = payload.get("tray")
    placed = payload.get("placed")

    if not is_tray(tray):
        return "INVALID"

    if not isinstance(placed, list):
        return "INVALID"

    rows = tray["rows"]
    cols = tray["cols"]
    blocked = tray["blocked"]

    # Validate placed cells
    validated_placed = []
    for cell in placed:
        if not isinstance(cell, (list, tuple)) or len(cell) != 2:
            return "INVALID"
        r, c = cell
        # Handle boolean values for row and column
        if isinstance(r, bool):
            r = 1 if r else 0
        if isinstance(c, bool):
            c = 1 if c else 0
        if not isinstance(r, int) or not isinstance(c, int):
            return "INVALID"
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return "INVALID"
        cell_tuple = (r, c)
        if cell_tuple in blocked:
            return "INVALID"
        if cell_tuple in validated_placed:
            return "INVALID"
        validated_placed.append(cell_tuple)

    # Calculate filled, open, and first_open
    filled = len(validated_placed)
    usable = rows * cols - len(blocked)
    open_count = usable - filled

    # Find first_open in reading order
    first_open = None
    for r in range(rows):
        for c in range(cols):
            cell = (r, c)
            if cell not in blocked and cell not in validated_placed:
                first_open = [r, c]
                break
        if first_open is not None:
            break

    return {
        "filled": filled,
        "open": open_count,
        "first_open": first_open
    }
